entity_extractor:
"""Rule-based span extractor on original text; this is not trained NER."""
import re
import json
import csv
from functools import lru_cache
from datetime import datetime,timedelta
from app.services.nlp.ontology import ontology
from app.config import DATASET_DIR, BACKEND_DIR
from app.services.dataset_loader import load_dataset

SPEED=re.compile(r'(?<!\w)(?:(?:about|around|maybe|लगभग)\s+)?(?P<value>\d{2,3})\s*(?P<unit>km\s*/\s*h|kmph|kph|किमी\s*/\s*घंटा)(?!\w)',re.I)
DATE_ISO=re.compile(r'\b\d{4}-\d{2}-\d{2}\b')
DATE_WORD=re.compile(r'\b\d{1,2}\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}\b',re.I)
ROAD=re.compile(r'\b(?:expressway|city road|highway|motorway|village road|residential road|urban road)\b|एक्सप्रेसवे|हाईवे|राजमार्ग',re.I)
VEHICLES=re.compile(r'(?<!\w)(?:auto[- ]rickshaw|e[- ]rickshaw|motorcycle|scooter|bike|car|bus|truck|lorry|motor car|मोटरसाइकिल|स्कूटर|कार|बस)(?!\w)',re.I)
INSURANCE=re.compile(r'\b(?:insurance|policy)\b.{0,24}\b(?:expired|valid|active|lapsed)\b|\b(?:no|without)\s+insurance\b|बीमा.{0,15}(?:खत्म|समाप्त|वैध)|\binsurance\s+expire(?:d)?\s+ho\s+gaya\b',re.I)
CHALLAN=re.compile(r'\b(?:did not receive|didn.t get|no|without)\s+(?:a\s+)?challan\b|\b(?:received|got|issued|paid)\s+(?:a\s+)?challan\b|चालान.{0,15}(?:नहीं|कटा|मिला)|\bchallan\s+kat\s+gaya\b',re.I)
LICENCE=re.compile(r'\b(?:licen[cs]e|dl)\b.{0,20}\b(?:expired|valid|suspended|seized)\b|\b(?:no|without)\s+(?:driving\s+)?licen[cs]e\b',re.I)
AGE=re.compile(r'\b(?P<age>\d{1,2})\s*(?:years? old|yrs? old|साल)\b',re.I)
AGE_LABEL=re.compile(r'(?:\bage\b|उम्र)\s*[:：-]\s*(?P<age>\d{1,2})',re.I)

@lru_cache(maxsize=1)
def status_vocabulary():
    """Only training annotations may supply status phrases used at inference."""
    manifest=BACKEND_DIR/'artifacts'/'nlp_split_manifest.csv'
    if not manifest.is_file():
        raise FileNotFoundError('Prepare the NLP training split before entity inference')
    with manifest.open(encoding='utf-8',newline='') as stream:
        allowed={row['utterance_id'] for row in csv.DictReader(stream) if row['derived_split']=='train'}
    return build_status_vocabulary(allowed)


def build_status_vocabulary(allowed_ids):
    """Create a vocabulary from a specified training fold only."""
    values={kind:set() for kind in ('CHALLAN_STATUS','LICENCE_STATUS','INSURANCE_STATUS')}
    _,rows=load_dataset(DATASET_DIR/'annotated_utterances.csv')
    for _,row in rows:
        if not isinstance(row,dict) or row.get('utterance_id') not in allowed_ids:continue
        try: annotations=json.loads(row.get('entity_annotations_json') or '[]')
        except json.JSONDecodeError:continue
        for item in annotations:
            if isinstance(item,dict) and item.get('slot_name') in values and isinstance(item.get('value'),str):
                values[item['slot_name']].add(item['value'].casefold())
    return {kind:sorted(items,key=len,reverse=True) for kind,items in values.items()}


def extract(text: str, reference_datetime: datetime | None=None, status_values=None):
    entities=[]
    def add(kind,match,value=None,method='rule'):
        entities.append({'type':kind,'text':match.group(0),'value':value or match.group(0),
                         'start':match.start(),'end':match.end(),'method':method,'confidence':None})
    for m in SPEED.finditer(text): add('OBSERVED_SPEED',m,m.group('value'))
    for m in VEHICLES.finditer(text): add('VEHICLE_CLASS',m)
    for m in ROAD.finditer(text): add('ROAD_TYPE',m)
    for m in DATE_ISO.finditer(text): add('EVENT_DATE',m)
    for m in DATE_WORD.finditer(text): add('EVENT_DATE',m)
    if reference_datetime:
        for m in re.finditer(r'\b(?:yesterday|today)\b|\b(?:कल|आज)\b',text,re.I):
            token=m.group(0).casefold()
            if token in {'yesterday','today','आज'}:
                day=(reference_datetime.date()-timedelta(days=1)) if token=='yesterday' else reference_datetime.date()
                add('EVENT_DATE',m,day.isoformat(),'relative_date')
            # Hindi कल can mean yesterday or tomorrow, so leave unresolved.
            else:add('EVENT_DATE',m,method='ambiguous_relative_date')
    for m in INSURANCE.finditer(text): add('INSURANCE_STATUS',m)
    for m in CHALLAN.finditer(text): add('CHALLAN_STATUS',m)
    for m in LICENCE.finditer(text): add('LICENCE_STATUS',m)
    for m in AGE.finditer(text): add('AGE',m,m.group('age'))
    for m in AGE_LABEL.finditer(text):
        if not any(e['type']=='AGE' and e['start']<=m.start('age')<e['end'] for e in entities):
            entities.append({'type':'AGE','text':m.group('age'),'value':m.group('age'),
                             'start':m.start('age'),'end':m.end('age'),'method':'rule','confidence':None})
    cues={'CHALLAN_STATUS':r'challan|चालान','LICENCE_STATUS':r'licen[cs]e|\bdl\b|लाइसेंस',
          'INSURANCE_STATUS':r'insurance|policy|बीमा'}
    for kind,phrases in (status_values if status_values is not None else status_vocabulary()).items():
        for phrase in phrases:
            for m in re.finditer(r'(?<!\w)'+re.escape(phrase)+r'(?!\w)',text,re.I):
                vicinity=text[max(0,m.start()-45):min(len(text),m.end()+45)]
                if not re.search(cues[kind],vicinity,re.I):continue
                if any(e['type']==kind and e['start']<=m.start()<e['end'] for e in entities):continue
                entities.append({'type':kind,'text':m.group(0),'value':m.group(0),
                                 'start':m.start(),'end':m.end(),'method':'annotation_vocabulary','confidence':None})
    # Match only dataset jurisdiction names and a few documented, unambiguous spellings.
    names={r['state_ut_name'].casefold():r['state_ut_name'] for r in ontology()['jurisdictions'].values() if r['jurisdiction_level']!='CENTRAL'}
    names['tamilnadu']='Tamil Nadu'
    for name in sorted(names,key=len,reverse=True):
        for m in re.finditer(r'(?<!\w)'+re.escape(name)+r'(?!\w)',text,re.I):
            if not any(e['type']=='STATE' and e['start']<=m.start()<e['end'] for e in entities):
                add('STATE',m)
    entities.sort(key=lambda e:(e['start'],e['end'],e['type']))
    return entities

normalizer:
"""Ground entity normalization in vehicle and jurisdiction CSV vocabularies."""
from datetime import date,datetime
from app.services.nlp.ontology import ontology

VEHICLE_ALIASES={
    'car':['VC_MOTORCAR'],'motor car':['VC_MOTORCAR'],'कार':['VC_MOTORCAR'],
    'auto-rickshaw':['VC_THREE_WHEELER_TRANSPORT'],'auto rickshaw':['VC_THREE_WHEELER_TRANSPORT'],
    'e-rickshaw':['VC_E_RICKSHAW'],
    'bike':['VC_MCWG','VC_MCWOG'],'motorcycle':['VC_MCWG','VC_MCWOG'],
    'मोटरसाइकिल':['VC_MCWG','VC_MCWOG'],'scooter':['VC_MCWG','VC_MCWOG'],'स्कूटर':['VC_MCWG','VC_MCWOG'],
    'bus':['VC_OMNIBUS','VC_MPV','VC_HPMV'],'बस':['VC_OMNIBUS','VC_MPV','VC_HPMV'],
    'truck':['VC_MGV','VC_HGV'],'lorry':['VC_MGV','VC_HGV'],
}

def normalize(entity):
    e=dict(entity);kind=e['type'];raw=e['text'];value=str(e['value'])
    e.update({'normalizedValue':None,'normalizedId':None,'status':'unresolved','vocabularySource':None,'alternatives':[]})
    if kind=='OBSERVED_SPEED':
        e.update(normalizedValue=str(int(value)),unit='km/h',status='resolved',vocabularySource='unit pattern')
        e['approximate']=any(x in raw.lower() for x in ('about','around','maybe','लगभग'))
    elif kind=='VEHICLE_CLASS':
        options=[x for x in VEHICLE_ALIASES.get(raw.casefold(),[]) if x in ontology()['vehicles']]
        e['alternatives']=options
        if len(options)==1:e.update(normalizedValue=ontology()['vehicles'][options[0]]['common_name'],normalizedId=options[0],status='resolved')
        elif options:e.update(normalizedValue='Vehicle class needs clarification',status='ambiguous')
        e['vocabularySource']='vehicle_classes.csv + documented informal aliases'
    elif kind=='STATE':
        lookup={r['state_ut_name'].casefold():r for r in ontology()['jurisdictions'].values() if r['jurisdiction_level']!='CENTRAL'}
        key=raw.casefold().replace('tamilnadu','tamil nadu')
        if key in lookup:e.update(normalizedValue=lookup[key]['state_ut_name'],normalizedId=lookup[key]['jurisdiction_id'],status='resolved')
        e['vocabularySource']='jurisdictions.csv'
    elif kind=='EVENT_DATE':
        try:
            if e['method']=='ambiguous_relative_date':return e
            if e['method']=='relative_date':day=date.fromisoformat(value)
            else:
                try:day=date.fromisoformat(raw)
                except ValueError:day=datetime.strptime(raw,'%d %B %Y').date()
            e.update(normalizedValue=day.isoformat(),status='resolved',vocabularySource='explicit/relative date parser')
        except ValueError:pass
    elif kind=='AGE':
        e.update(normalizedValue=str(int(value)),status='resolved',vocabularySource='provisional AGE extractor; absent from slot_schema.csv')
    elif kind=='ROAD_TYPE':
        e.update(normalizedValue=raw.casefold(),status='resolved',vocabularySource='road-type phrase rules')
    elif kind in {'INSURANCE_STATUS','CHALLAN_STATUS','LICENCE_STATUS'}:
        lower=raw.casefold()
        negative=any(s in lower for s in ('no ','without ','not ','n.t ','नहीं'))
        if 'unknown' in lower:
            e.update(normalizedValue='unknown',status='unresolved',vocabularySource='annotation status vocabulary')
        else:
            terms=('under dispute','referred to court','disqualified','suspended','seized',
                   'unpaid','paid','issued','expired','lapsed','active','valid')
            identified=next((term for term in terms if term in lower),None)
            e.update(normalizedValue='absent' if negative else identified,
                     status='resolved' if negative or identified else 'unresolved',
                     vocabularySource='annotation status vocabulary and negation rules')
    return e

slot_detector:
"""Intent-specific required slots; unsupported conditions stay unresolved."""
import json
from app.services.nlp.ontology import ontology

PROVISIONAL_AGE={'intent_id':'INT016','slot_name':'AGE','status':'provisional',
                 'source':'INT016.conditional_slot_ids and 26 annotated utterances; absent from slot_schema.csv'}

def detect_slots(intent_id: str, entities: list[dict]):
    configured=ontology()['slots'].get(intent_id,[])
    by_type={}
    for entity in entities:by_type.setdefault(entity['type'],[]).append(entity)
    missing=[];unresolved=[];found=0;total=0
    for row in sorted(configured,key=lambda r:int(r['ask_priority'] or 999)):
        slot=row['slot_name'];level=row['required_level']
        condition=json.loads(row['required_when_json'] or '{}').get('when')
        values=by_type.get(slot,[])
        valid=[x for x in values if x['status']=='resolved']
        conflicting=len({str(x['normalizedValue']) for x in valid})>1
        ambiguous=bool(values) and (not valid or conflicting)
        if level=='required' and condition=='intent_context':
            total+=1
            if valid and not conflicting:found+=1
            else:
                item={'slot':slot,'label':row['slot_display_name'],'priority':int(row['ask_priority'] or 999),
                      'question':row['question_template_en'],'reason':'ambiguous_or_conflicting' if ambiguous else 'missing'}
                missing.append(item)
        elif level=='conditional':
            unresolved.append({'slot':slot,'reason':'condition_not_implemented',
                               'condition':condition,'present':bool(valid)})
        elif level=='optional':
            continue
        else:
            unresolved.append({'slot':slot,'reason':'unsupported_requirement','condition':condition})
    if intent_id=='INT016':
        unresolved.append({'slot':'AGE','reason':'provisional_schema_gap',
                           'condition':'only_when_relevant_to_rule_or_situation','present':bool(by_type.get('AGE'))})
    missing.sort(key=lambda x:x['priority'])
    percentage=round(found/total*100) if total else 0
    if unresolved and percentage==100:percentage=99
    status='needs_context' if missing else 'conditional_unresolved' if unresolved else 'ready_for_review' if total else 'no_configured_required_slots'
    return {'missingSlots':missing,'unresolvedSlots':unresolved,
            'readiness':{'found':found,'total':total,'percentage':percentage,'status':status}}
